function buildBlock(r: BlockRef): MasterExamBlock {
  const [src, i, label, nos, de, grp] = r;
  let base: any = src === 0 ? TOPIK_SHORT_DATA[i] : src === 1 ? TOPIK_DIALOG_DATA[i] : TOPIK_READ_BLOCKS[i];

  // Câu 27–28 và 29–30 là block hai câu. Sau khi bổ sung thêm các bộ tranh
  // 15–16, chỉ số cũ của hai nhóm này bị lệch nhưng thông tin đề/cụm vẫn đúng.
  // Tìm lại theo đề + cụm để luôn lấy đủ cả hai câu và đúng phần nghe tương ứng.
  if (src === 1 && (grp === '27-28' || grp === '29-30')) {
    const pairedDialog = TOPIK_DIALOG_DATA.find(item => {
      const examLabels = String(item.de || '').split('/').map(value => value.trim());
      return item.grp === grp && examLabels.includes(String(de).trim());
    });
    if (pairedDialog) base = pairedDialog;
  }
  const block: MasterExamBlock = {
    label,
    qs: (base.qs || []).map((q: any, k: number) => {
      const no = nos[k] === undefined || nos[k] === null ? undefined : nos[k];
      const optionImages = q.optionImages || getTopikPictureOptions(base.de, base.cau);
      return {
        ...q,
        ...(no === undefined ? {} : { no }),
        ...(optionImages ? { optionImages } : {}),
      };
    }),
    explain: base.meta || base.explain || []
  };
  if (de) block.de = de;
  if (grp) block.grp = grp;
  if (base.lines) block.lines = base.lines;
  if (base.text) block.text = base.text;
  if (base.warn) block.warn = true;
  return block;
}

const PICTURE_SET_BY_MOCK_ID: Record<string, number> = {
  mock6: 6,
  mock7: 7,
  mock8: 8,
  mock9: 9,
};

function buildTests(refs: TestRef[]): MasterExam[] {
  return refs.map(t => {
    const pictureSet = PICTURE_SET_BY_MOCK_ID[t.id];
    const blockRefs = t.b.map((ref): BlockRef => {
      const questionNo = Number(ref[3][0]);
      if (!pictureSet || ref[0] !== 1 || (questionNo !== 15 && questionNo !== 16)) return ref;

      const dialogIndex = (pictureSet - 1) * 2 + (questionNo === 16 ? 1 : 0);
      return [ref[0], dialogIndex, ref[2], ref[3], ref[4], ref[5]];
    });

    return {
      id: t.id,
      kind: t.kind,
      de: t.de,
      title: t.title,
      sub: t.sub,
      n: t.n,
      missing: t.missing,
      blocks: blockRefs.map(buildBlock),
    };
  });
}

const expandPictureChoiceGroup = (tests: MasterExam[]): MasterExam[] => tests.map((test) => {
  if (test.id !== 'g15-16') return test;

  const blocks = TOPIK_DIALOG_DATA.slice(0, 18).map((item, index) => buildBlock([
    1,
    index,
    `${item.de} · ${item.cau}`,
    [Number(item.cau.match(/\d+/)?.[0])],
    item.de,
    item.grp,
  ]));

  return {
    ...test,
    sub: '9 bộ · 18 câu chọn tranh',
    n: 18,
    blocks,
  };
});

const TOPIK_25_26_GROUP: MasterExam = {
  id: 'g25-26',
  kind: 'grp',
  de: '25-26',
  title: 'Câu 25–26 · Nghe thông báo',
  sub: '5 bộ mới · Lý do nói + nội dung đúng',
  n: 10,
  blocks: TOPIK_LISTENING_25_26.map((item, index) => ({
    label: `Bộ ${index + 1} · Câu 25–26`,
    de: item.de,
    grp: item.grp,
    lines: item.lines,
    warn: item.warn,
    qs: item.qs,
    explain: item.meta,
  })),
};

const addListening25_26 = (tests: MasterExam[]): MasterExam[] => tests.map((test, index) => {
  // Đề thi thử toàn phần phải luôn đủ 70 câu. Năm bộ 25–26 được luân phiên
  // cho đề 6–10; đề nghe theo kỳ vẫn chỉ bổ sung trong phạm vi dữ liệu có sẵn.
  if (test.kind !== 'mock' && index >= TOPIK_LISTENING_25_26.length) return test;
  const listeningBlock = TOPIK_25_26_GROUP.blocks[index % TOPIK_25_26_GROUP.blocks.length];
  const insertAt = test.blocks.findIndex(block => block.qs.some(q => Number(q.no) >= 27));
  const blocks = [...test.blocks];
  blocks.splice(insertAt >= 0 ? insertAt : blocks.length, 0, listeningBlock);
  const seenQuestionNumbers = new Set<number>();
  const uniqueBlocks = blocks
    .map(block => ({
      ...block,
      qs: block.qs.filter(question => {
        const no = Number(question.no);
        if (!Number.isFinite(no)) return true;
        if (seenQuestionNumbers.has(no)) return false;
        seenQuestionNumbers.add(no);
        return true;
      }),
    }))
    .filter(block => block.qs.length > 0);
  return {
    ...test,
    n: uniqueBlocks.reduce((sum, block) => sum + block.qs.length, 0),
    missing: (test.missing || []).filter(value => value !== '25' && value !== '26'),
    blocks: uniqueBlocks,
  };
});

const appendSupplementBlocks = (
  tests: MasterExam[],
  supplements: Record<string, MasterExamBlock[]>,
): MasterExam[] => tests.map((test) => {
  // Cụm 15–16 đã dùng đủ 9 bộ tranh thật; không ghép lại các câu chữ bổ sung cũ.
  const addedBlocks = test.id === 'g15-16' ? [] : supplements[test.id] || [];
  const blocks = addedBlocks.length > 0 ? [...test.blocks, ...addedBlocks] : test.blocks;
  const totalQuestions = blocks.reduce((sum, block) => sum + block.qs.length, 0);
  return {
    ...test,
    n: totalQuestions,
    sub: addedBlocks.length > 0 ? `${test.sub} · ${totalQuestions} câu luyện` : test.sub,
    blocks,
  };
});

const baseGroupedTests = expandPictureChoiceGroup(buildTests(REF_GROUPS));
const group25InsertAt = baseGroupedTests.findIndex((test) => test.id === 'g27-28');
const orderedGroupedTests = [
  ...baseGroupedTests.slice(0, group25InsertAt),
  TOPIK_25_26_GROUP,
  ...baseGroupedTests.slice(group25InsertAt),
];

export const TOPIK_GROUPS_DATA: MasterExam[] = appendSupplementBlocks(
  orderedGroupedTests,
  TOPIK_GROUP_SUPPLEMENTS,
);
export const TOPIK_READS_DATA: MasterExam[] = appendSupplementBlocks(
  buildTests(REF_READS),
  TOPIK_READ_SUPPLEMENTS,
);
export const TOPIK_EXAMS_DATA: MasterExam[] = addListening25_26(buildTests(REF_EXAMS));
export const TOPIK_MOCKS_DATA: MasterExam[] = addListening25_26(buildTests(REF_MOCKS));
